/*
  GENERATED by `npm run catalogue:gen` from db/seed/catalogue/*.json. Do not edit by hand: change the JSON and regenerate.
  9 regions, 3 ships, 99 ports, 32 patterns, 68 sailings.
  Idempotent MERGEs; it never deletes. Run after the other reference seeds (db/seed/reference/run-all.sql does): it reads ref.Ships, ref.Ports,
  ref.CabinCategories and ref.Sailings rows that 01-ship.sql and 02-itinerary.sql create, and only fills the catalogue columns on those rows.
*/
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO

-- ref.Regions: 9 rows
MERGE ref.Regions AS t
USING (VALUES
  (N'caribbean', N'Caribbean', 1),
  (N'western-med', N'Western Mediterranean', 2),
  (N'eastern-med', N'Eastern Mediterranean and Adriatic', 3),
  (N'atlantic', N'Atlantic crossings and islands', 4),
  (N'northern-europe', N'Northern Europe', 5),
  (N'scandinavia', N'Scandinavia, Baltic and Iceland', 6),
  (N'japan-korea', N'Japan and Korea', 7),
  (N'southeast-asia', N'Southeast Asia', 8),
  (N'australia-nz', N'Australia and New Zealand', 9)
) AS s ([Id], [Name], [SortOrder])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Name] = s.[Name], t.[SortOrder] = s.[SortOrder]
WHEN NOT MATCHED THEN INSERT ([Id], [Name], [SortOrder]) VALUES (s.[Id], s.[Name], s.[SortOrder]);
GO

-- ref.Ships: 3 rows (a seeded ship keeps its profile; only the catalogue columns are filled)
MERGE ref.Ships AS t
USING (VALUES
  (N'sun-princess', N'Sun Princess', N'Sphere class', 17, 177882, 4300, N'America/New_York', CAST(N'{"id":"sun-princess","name":"Sun Princess","className":"Sphere class","entered":2024,"tonnage":177882,"length":"1,133 ft","guests":4300,"crew":1600,"staterooms":2157,"decks":17,"intro":"Princess'' newest ship, built around the Piazza, a three-level gathering place under a glass Sphere, and the Dome, a glass-roofed pool by day and a theatre by night.","highlights":[{"title":"The Piazza","body":"Three levels of cafes, bars and live music under the Sphere."},{"title":"The Dome","body":"A pool by day and acrobatic theatre at night."},{"title":"Princess Arena","body":"The main show venue, set up three ways for different productions."}]}' AS NVARCHAR(MAX)), 1133, 155, 1600, 2157, 2024, N'Princess'' newest ship, built around the Piazza, a three-level gathering place under a glass Sphere, and the Dome, a glass-roofed pool by day and a theatre by night.', N'aboard'),
  (N'sky-princess', N'Sky Princess', N'Royal class', 19, 145281, 3660, N'America/New_York', CAST(N'{"id":"sky-princess","name":"Sky Princess","className":"Royal class","entered":2019,"tonnage":145281,"length":"1,080 ft","guests":3660,"crew":1346,"staterooms":1830,"decks":19,"intro":"A Royal-class ship known for the SeaWalk, a glass-bottomed walkway that reaches out over the sea, and a three-deck Piazza.","highlights":[{"title":"SeaWalk","body":"A glass-bottomed walkway that extends about 28 feet beyond the side of the ship."},{"title":"The Sanctuary","body":"An adults-only retreat with private cabanas."},{"title":"Sky Suites","body":"Two top-deck suites with wraparound balconies and 270-degree views."},{"title":"Movies Under the Stars","body":"A big outdoor screen above the pool deck."}]}' AS NVARCHAR(MAX)), 1080, 126, 1346, 1830, 2019, N'A Royal-class ship known for the SeaWalk, a glass-bottomed walkway that reaches out over the sea, and a three-deck Piazza.', N'browse'),
  (N'sapphire-princess', N'Sapphire Princess', N'Gem class', 13, 115875, 2670, N'Asia/Tokyo', CAST(N'{"id":"sapphire-princess","name":"Sapphire Princess","className":"Gem class","entered":2004,"tonnage":115875,"length":"951 ft","guests":2670,"crew":1100,"staterooms":null,"decks":13,"intro":"A mid-sized Gem-class ship with an Italian-inspired Piazza, an adults-only Serenity pool and a long Asia and Australia season.","highlights":[{"title":"The Sanctuary","body":"An adults-only retreat, the last ship to receive one."},{"title":"The Piazza","body":"Italian-inspired, with an international cafe and a wine bar."},{"title":"Skywalkers Nightclub","body":"A nightclub on the top deck."},{"title":"Movies Under the Stars","body":"An outdoor screen on the pool deck."}]}' AS NVARCHAR(MAX)), 951, 121, 1100, NULL, 2004, N'A mid-sized Gem-class ship with an Italian-inspired Piazza, an adults-only Serenity pool and a long Asia and Australia season.', N'browse')
) AS s ([Id], [Name], [Class], [Decks], [Tonnage], [Capacity], [HomeZone], [ProfileJson], [LengthFt], [BeamFt], [Crew], [Staterooms], [Entered], [Intro], [Depth])
