) AS s ([Id], [Kind], [Name], [Cuisine], [Deck], [DressCode], [Capacity], [Walkin], [OpenFrom], [OpenTo], [CoverCents], [Description], [Hours], [ShipId])
ON t.[Id] = s.[Id]
WHEN MATCHED THEN UPDATE SET t.[Kind] = s.[Kind], t.[Name] = s.[Name], t.[Cuisine] = s.[Cuisine], t.[Deck] = s.[Deck], t.[DressCode] = s.[DressCode], t.[Capacity] = s.[Capacity], t.[Walkin] = s.[Walkin], t.[OpenFrom] = s.[OpenFrom], t.[OpenTo] = s.[OpenTo], t.[CoverCents] = s.[CoverCents], t.[Description] = s.[Description], t.[Hours] = s.[Hours], t.[ShipId] = s.[ShipId]
WHEN NOT MATCHED THEN INSERT ([Id], [Kind], [Name], [Cuisine], [Deck], [DressCode], [Capacity], [Walkin], [OpenFrom], [OpenTo], [CoverCents], [Description], [Hours], [ShipId]) VALUES (s.[Id], s.[Kind], s.[Name], s.[Cuisine], s.[Deck], s.[DressCode], s.[Capacity], s.[Walkin], s.[OpenFrom], s.[OpenTo], s.[CoverCents], s.[Description], s.[Hours], s.[ShipId]);
GO

